-- Description: Current active relationship for LNK_SCHEDULEDITEMS_HRREPRESENTATIVE using ROW_NUMBER()
-- Generated by: bv pipeline generate transform
-- Link Type: RELATIONSHIP_BASED_LINK

WITH RANKED_RELATIONSHIPS AS (
SELECT
    l.LNK_SCHEDULEDITEMS_HRREPRESENTATIVE_HKEY AS LNK_SCHEDULEDITEMS_HRREPRESENTATIVE_HKEY,
    l.SCHEDULEDITEMS_HKEY AS SCHEDULEDITEMS_HKEY,
    l.HR_REPRESENTATIVE_HKEY AS HR_REPRESENTATIVE_HKEY,

    -- TODO: use generated tag instead of well-known name _CURRENT_ACTIVE_TIMESTAMP
    ls._CURRENT_ACTIVE_TIMESTAMP AS _CURRENT_RELATIONSHIP_TIMESTAMP, -- was ls.LOAD_DATE

    ROW_NUMBER() OVER (
        PARTITION BY l.SCHEDULEDITEMS_HKEY -- parent hub hk
        ORDER BY ls._CURRENT_ACTIVE_TIMESTAMP DESC -- TODO: as above. Was ls.LOAD_DATE
    ) AS row_num

FROM {{ source('eli_dv_rv', 'lnk_scheduleditems_hrrepresentative') }} l
INNER JOIN {{ ref('lks_erc_scheduleditems_hrrepresentative_curr') }} ls
    ON l.LNK_SCHEDULEDITEMS_HRREPRESENTATIVE_HKEY = ls.LNK_SCHEDULEDITEMS_HRREPRESENTATIVE_HKEY
)

SELECT * EXCLUDE (row_num)
FROM RANKED_RELATIONSHIPS
WHERE row_num = 1
